def check_task(root: Path) -> bool:
    required = ["flow_plane.py", "flow_plane.csv", "summary.txt"]
    if not require_files(root, required):
        return False

    summary = parse_floats(read_text(root / "summary.txt"))
    if not floats_close(summary, EXPECTED_SUMMARY):
        return False

    lines = [ln.strip() for ln in read_text(root / "flow_plane.csv").splitlines() if ln.strip()]
    if len(lines) != len(EXPECTED_FLOW) + 1:
        return False

    header = [h.strip() for h in lines[0].split(',')]
    if header != EXPECTED_HEADER:
        return False

    for actual_ln, expected_row in zip(lines[1:], EXPECTED_FLOW):
        parts = [p.strip() for p in actual_ln.split(',')]
        if len(parts) != 3:
            return False
        try:
            nums = [float(parts[0]), float(parts[1]), float(parts[2])]
        except ValueError:
            return False
        for a, e in zip(nums, expected_row):
            if not math.isclose(a, e, rel_tol=REL_TOL, abs_tol=ABS_TOL):
                return False
    return True

def evaluate() -> int:
    root = Path("/home/user/Desktop")
    try:
        ok = check_task(root)
    except Exception:
        ok = False
    return 1 if ok else 0


def main() -> int:
    result = evaluate()
    print("True" if result == 1 else "False")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
